//! The committed `assets/meh.ico` is generated by `cargo run --example
//! gen_icon`. Never edit it by hand.

const ICO: &[u8] = include_bytes!("../assets/meh.ico");

fn u16_at(i: usize) -> u16 {
    u16::from_le_bytes([ICO[i], ICO[i + 1]])
}

fn u32_at(i: usize) -> u32 {
    u32::from_le_bytes([ICO[i], ICO[i + 1], ICO[i + 2], ICO[i + 3]])
}

#[test]
fn ico_header_has_four_frames() {
    // ICONDIR: reserved 0, type 1 (icon), count 4.
    assert_eq!(&ICO[..6], &[0, 0, 1, 0, 4, 0]);
}

#[test]
fn ico_frames_are_32bpp_dibs_matching_icon_rgba() {
    for (n, size) in [16u32, 32, 48, 64].into_iter().enumerate() {
        let entry = 6 + n * 16;
        assert_eq!(ICO[entry] as u32, size, "width");
        assert_eq!(ICO[entry + 1] as u32, size, "height");
        assert_eq!(u16_at(entry + 6), 32, "bit count");
        let len = u32_at(entry + 8) as usize;
        let off = u32_at(entry + 12) as usize;
        assert!(off + len <= ICO.len());
        // BITMAPINFOHEADER: 40 bytes, height doubled (XOR + AND masks).
        assert_eq!(u32_at(off), 40);
        assert_eq!(u32_at(off + 4), size);
        assert_eq!(u32_at(off + 8), size * 2);
        // The bottom-left pixel of the DIB is the top-left of the image:
        // a transparent corner. The center is opaque.
        let px = off + 40;
        assert_eq!(ICO[px + 3], 0, "corner alpha at {size}");
        let c = (size / 2) as usize;
        let center = px + ((size as usize - 1 - c) * size as usize + c) * 4;
        let rgba = meh::icon::rgba(size);
        let src = (c * size as usize + c) * 4;
        // BGRA in the file, RGBA in memory.
        assert_eq!(
            [
                ICO[center + 2],
                ICO[center + 1],
                ICO[center],
                ICO[center + 3]
            ],
            [rgba[src], rgba[src + 1], rgba[src + 2], rgba[src + 3]],
            "center pixel at {size}"
        );
    }
}
